18: const RANDOM_SEED_LEN = 44;
19: const AES_KEY_LEN = 32;
20: const KEY_ID_LEN = 1;
21: const EC_PUBKEY_LEN = 65;
22: const HEADER_LEN = 98; // 32 + 1 + 65
23: const GCM_IV_LEN = 12;
24: const GCM_TAG_LEN = 16;
