62:     }
63:     wasmBuffer = res.body;
64:     try {
65:       fs.writeFileSync(wasmPath, wasmBuffer);
66:     } catch (_) {
67:       // Ignore write errors in read-only filesystems
68:     }
69:   }
70: 
71:   cachedWasmModule = await WebAssembly.compile(wasmBuffer);
72:   return cachedWasmModule;
73: }
