279: /**
280:  * Main export: Resolves stream with multi-server fallback.
281:  * 
282:  * @param {object} options
283:  * @returns {Promise<{ success: boolean, playlist: string, originalUrl: string, streamUrl: string, server: string, format: string, captions: Array, rawStream: object }>}
284:  */
285: async function resolveStream(options) {
286:   const tmdbId = options.tmdbId;
287:   const type = options.type || 'movie';
288:   const season = options.season;
289:   const episode = options.episode;
290:   const server = options.server || 'secret';
291:   const fallback = options.fallback !== false;
