293:   if (!tmdbId) {
294:     throw new Error('tmdbId is required for stream resolution');
295:   }
296: 
297:   const wasmModule = await initWasm();
298:   const clusterData = await getServers();
299:   const serverList = Array.isArray(clusterData.servers) ? clusterData.servers : [];
300:   const serverNames = serverList.map(function (s) { return s.name; });
301: 
302:   // If cluster list is empty, supply default known servers
303:   if (serverNames.length === 0) {
304:     serverNames.push('secret', 'Nebula', 'Lisbon', 'Solara', 'Athens');
305:   }
306: 
307:   // Build candidate order: preferred server first if specified
308:   const candidates = [];
309:   if (server && server !== 'auto' && serverNames.indexOf(server) !== -1) {
310:     candidates.push(server);
311:   }
312:   for (let i = 0; i < serverNames.length; i++) {
313:     const s = serverNames[i];
314:     if (candidates.indexOf(s) === -1) {
315:       candidates.push(s);
316:     }
317:   }
318: 
319:   const errors = [];
320:   for (let j = 0; j < candidates.length; j++) {
321:     const candidate = candidates[j];
322:     try {
323:       const result = await resolveSingleServer({
324:         server: candidate,
325:         type: type,
326:         tmdbId: tmdbId,
327:         season: season,
328:         episode: episode,
329:         wasmModule: wasmModule
330:       });
331: 
332:       return {
333:         success: true,
334:         playlist: result.playlist,
335:         originalUrl: result.playlist,
336:         streamUrl: result.playlist,
